{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The aim of this review is to summarize the available evidence about secondary attack rates (defined as the probability that an infected individual will transmit the disease to a susceptible individual) among the contacts of individuals with SARS-CoV-2 with different symptom status to provide information about how contagious they are, and their role in driving the pandemic.",
      "reason": "The Introduction ends with an explicit objective statement, and the abstract's Purpose section restates it ('This living review aims to critically appraise available data about secondary attack rates from people with asymptomatic, pre-symptomatic and symptomatic SARS-CoV-2 infection.'), clearly defining the review question including the population (contacts of index cases), exposure (symptom status), and outcome (secondary attack rate)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of transmission/secondary attack rates in observational outbreak and contact-tracing studies, not a review of intervention effects, so formal PICO-stated planned comparisons do not apply."
    }
  ],
  "confidence": 90
}

{
